"""Small standalone commands for the xan-compatible CLI."""
import csv
import sys


def _args(argv):
    opts = {"no_headers": False, "delimiter": ",", "output": None}
    positional = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ("-n", "--no-headers"):
            opts["no_headers"] = True
        elif a in ("-d", "--delimiter", "-o", "--output"):
            i += 1
            if i >= len(argv): raise ValueError("missing value for " + a)
            opts["delimiter" if a in ("-d", "--delimiter") else "output"] = argv[i]
        elif a.startswith("--delimiter="):
            opts["delimiter"] = a.split("=", 1)[1]
        elif a.startswith("--output="):
            opts["output"] = a.split("=", 1)[1]
        elif a in ("--tabs", "--crlf", "--ascii", "--quote-always", "--quote-never"):
            pass
        elif a in ("-t", "--out-delimiter", "--quote", "--escape"):
            i += 1
            if i >= len(argv): raise ValueError("missing value for " + a)
        elif a == "--":
            positional.extend(argv[i + 1:]); break
        elif a.startswith("-") and a != "-":
            raise ValueError("unexpected option: " + a)
        else:
            positional.append(a)
        i += 1
    if len(opts["delimiter"]) != 1: raise ValueError("delimiter must be a single character")
    return opts, positional


def _read(path, delim):
    src = open(path, "r", newline="", encoding="utf-8-sig") if path and path != "-" else sys.stdin
    try: return list(csv.reader(src, delimiter=delim))
    finally:
        if src is not sys.stdin: src.close()


def _write(rows, path, delim, **kwargs):
    dest = open(path, "w", newline="", encoding="utf-8") if path else sys.stdout
    try:
        w = csv.writer(dest, delimiter=delim, lineterminator=kwargs.get("lineterminator", "\n"),
                       quotechar=kwargs.get("quotechar", '"'), quoting=kwargs.get("quoting", csv.QUOTE_MINIMAL),
                       escapechar=kwargs.get("escapechar"))
        w.writerows(rows)
    finally:
        if dest is not sys.stdout: dest.close()


def run(command, argv):
    if command not in ("reverse", "fmt"):
        return False
    try:
        opts, pos = _args(argv)
        if len(pos) > 1: raise ValueError("expected at most one input file")
        path = pos[0] if pos else None
        rows = _read(path, opts["delimiter"])
        if command == "reverse":
            if opts["no_headers"]: rows.reverse()
            elif rows: rows = rows[:1] + rows[:0:-1]
            _write(rows, opts["output"], opts["delimiter"])
            return True
        outdelim, term, quote, quoting, escape = ",", "\n", '"', csv.QUOTE_MINIMAL, None
        i = 0
        while i < len(argv):
            a = argv[i]
            if a in ("-t", "--out-delimiter", "--quote", "--escape"):
                i += 1
                if i >= len(argv): raise ValueError("missing value for " + a)
                if a in ("-t", "--out-delimiter"): outdelim = argv[i]
                elif a == "--quote": quote = argv[i]
                else: escape = argv[i]
            elif a == "--tabs": outdelim = "\t"
            elif a == "--crlf": term = "\r\n"
            elif a == "--quote-always": quoting = csv.QUOTE_ALL
            elif a == "--quote-never": quoting = csv.QUOTE_NONE
            elif a == "--ascii": outdelim = "\x1f"; term = "\x1e"
            i += 1
        if len(outdelim) != 1 or len(quote) != 1 or (escape is not None and len(escape) != 1):
            raise ValueError("delimiter, quote and escape must be single characters")
        _write(rows, opts["output"], outdelim, lineterminator=term, quotechar=quote, quoting=quoting, escapechar=escape)
        return True
    except (OSError, csv.Error, ValueError) as e:
        print("error: " + str(e), file=sys.stderr)
        return True

#!/usr/bin/env python3
import sys,csv,re,random,io,os

def read_csv(path, delim=','):
    f=sys.stdin if path in (None,'-') else open(path, newline='', encoding='utf-8-sig')
    try: rows=list(csv.reader(f,delimiter=delim))
    finally:
        if f is not sys.stdin:f.close()
    return rows

def write(rows, delim=',', out=None):
    f=sys.stdout if not out or out=='-' else open(out,'w',newline='',encoding='utf-8')
    try:
        w=csv.writer(f,delimiter=delim,lineterminator='\n')
        w.writerows(rows)
    finally:
        if f is not sys.stdout:f.close()

def parse(args):
    opts={}; pos=[]; i=0
    takes={'-d':'delimiter','--delimiter':'delimiter','-o':'output','--output':'output','-s':'select','--select':'select','-f':'flag','--flag':'flag','-c':'count','--count':'count','-R':'replace','--replace':'replace','-L':'levenshtein','--levenshtein':'levenshtein','-D':'damerau','--damerau-levenshtein':'damerau','--seed':'seed','-g':'groupby','--groupby':'groupby','-w':'weight','--weight':'weight','-l':'limit','--limit':'limit'}
    switches={'-n':'no_headers','--no-headers':'no_headers','-e':'exact','--exact':'exact','-r':'regex','--regex':'regex','-i':'ignore_case','--ignore-case':'ignore_case','-v':'invert','--invert-match':'invert','-N':'nonempty','--non-empty':'nonempty','-E':'empty','--empty':'empty','-k':'duplicates','--keep-duplicates':'duplicates','-S':'sorted','--sorted':'sorted','--keep-last':'last','-A':'all','--all':'all','--overlapping':'overlap','--left':'left'}
    while i<len(args):
        a=args[i]
        if a=='--':pos.extend(args[i+1:]);break
        if a in switches:opts[switches[a]]=True
        elif a in takes:
            i+=1
            if i>=len(args):raise ValueError('missing option argument')
            opts[takes[a]]=args[i]
        elif a.startswith('-') and a!='-': pos.append(a)
        else:pos.append(a)
        i+=1
    return opts,pos

def indices(spec,header,n):
    names=header or [str(i) for i in range(n)]; result=[]
    for tok in spec.split(','):
        tok=tok.strip()
        if ':' in tok:
            a,b=tok.split(':',1)
            def ix(x,default):
                if not x:return default
                try:v=int(x);return v if v>=0 else n+v
                except:return names.index(x)
            lo,hi=ix(a,0),ix(b,n-1)
            result.extend(range(max(0,lo),min(n-1,hi)+1))
        else:
            try:v=int(tok);v=v if v>=0 else n+v
            except:
                m=re.match(r'^(.*)\[(-?\d+)\]$',tok)
                if m:
                    matches=[i for i,x in enumerate(names) if x==m.group(1)];v=matches[int(m.group(2)) if int(m.group(2))>=0 else len(matches)+int(m.group(2))]
                else:v=names.index(tok)
            if 0<=v<n:result.append(v)
    return result

def run(cmd,args):
    o,p=parse(args); d=o.get('delimiter',',')
    if len(d)!=1:raise ValueError('delimiter must be a single character')
    if cmd=='sample':
        if not p:raise ValueError('missing sample size')
        size=int(p.pop(0)); path=p[0] if p else '-'
    elif cmd=='search':path=p[1] if len(p)>1 else '-'
    else:path=p[-1] if p else '-'
    rows=read_csv(path,d); nh=o.get('no_headers',False); header=[] if nh else (rows.pop(0) if rows else [])
    out=o.get('output')
    if cmd=='dedup':
        n=len(rows[0]) if rows else len(header); cols=indices(o.get('select',','.join(map(str,range(n)))),header,n)
        seen={}; marked=[]
        for idx,row in enumerate(rows):
            key=tuple(row[j] if j<len(row) else '' for j in cols)
            dup=key in seen
            if o.get('last') and dup:
                marked[seen[key]]=None
            if not dup or o.get('last'):
                seen[key]=len(marked); marked.append((row,dup))
            else:marked.append((row,True))
        if o.get('duplicates'): result=[r for r,dup in marked if dup]
        elif o.get('flag'):
            name=o['flag'];header.append(name);result=[r+['true' if dup else 'false'] for r,dup in marked]
        else:result=[r for r,dup in marked if not dup]
        if header:result=[header]+result
        write(result,d,out);return
    if cmd=='search':
        pats=[]
        while p and p[0].startswith('-P'):
            pats.append(p.pop(0)[2:] or p.pop(0))
        pat=p[0] if p else ''
        if not pats:pats=[pat]
        n=len(rows[0]) if rows else len(header); cols=indices(o.get('select',','.join(map(str,range(n)))),header,n)
        insensitive=o.get('ignore_case'); flags=re.I if insensitive else 0
        regexes=[]
        if o.get('regex'):
            regexes=[re.compile(x,flags) for x in pats]
        def matches(cell,pat_i):
            if o.get('empty'):return cell==''
            if o.get('nonempty'):return cell!=''
            pat=pats[pat_i]; c=cell
            if o.get('exact'):return c.casefold()==pat.casefold() if insensitive else c==pat
            if o.get('regex'):return bool(regexes[pat_i].search(c))
            return pat.casefold() in c.casefold() if insensitive else pat in c
        result=[]
        for row in rows:
            cells=[row[j] if j<len(row) else '' for j in cols]
            per=[[matches(c,k) for c in cells] for k in range(len(pats))]
            yes=any(any(x) for x in per) if len(pats)==1 else any(any(x) for x in per)
            if o.get('all') and len(pats)==1:yes=bool(per[0]) and all(per[0])
            if o.get('invert'):yes=not yes
            if o.get('replace') is not None:
                rr=row[:]
                for j in cols:
                    if j<len(rr):
                        for pat in pats:rr[j]=re.sub(pat,o['replace'],rr[j]) if o.get('regex') else rr[j].replace(pat,o['replace'])
                result.append(rr)
            elif o.get('count'):
                count=sum(len(rx.findall(c)) if o.get('regex') else c.count(pa) for c in cells for rx,pa in zip(regexes or [None]*len(pats),pats))
                if count or o.get('left'):result.append(row+[str(count)])
            elif o.get('flag'):result.append(row+['true' if yes else 'false'])
            elif yes:result.append(row)
            if o.get('limit') and len(result)>=int(o['limit']):break
        if header:
            if o.get('flag'):header.append(o['flag'])
            if o.get('count'):header.append(o['count'])
            result=[header]+result
        write(result,d,out);return
    if cmd=='sample':
        rng=random.Random(int(o['seed']) if 'seed' in o else None)
        if o.get('groupby'):
            names=o['groupby'];cols=indices(names,header,len(rows[0]) if rows else len(header)); groups={}
            for r in rows:groups.setdefault(tuple(r[j] if j<len(r) else '' for j in cols),[]).append(r)
            data=[]
            for g in groups.values():data.extend(rng.sample(g,min(size,len(g))))
        else:data=rng.sample(rows,min(size,len(rows)))
        write(([header] if header else [])+data,d,out);return
    raise ValueError('unknown command')

def main():
    args=sys.argv[1:]
    if not args or args[0] in ('-h','--help'):
        print('Usage: xan [options] <command> [<args>...]');return
    if args[0]=='--version':print('xan');return
    cmd=args.pop(0)
    aliases={'freq':'frequency'};cmd=aliases.get(cmd,cmd)
    try:run(cmd,args)
    except Exception as e:
        print(f'error: {e}',file=sys.stderr);sys.exit(1)

if __name__=='__main__':main()
