"""CSV row width normalization helpers for xan-compatible CLI."""
import csv
import sys


def run(cmd, argv):
    """Run fixlengths command. Returns True when the command was handled."""
    if cmd not in ('fixlengths', 'transpose', 't'):
        return False
    delim = ','
    out = None
    target = None
    length = None
    trust = False
    inp = None
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ('-h', '--help'):
            if cmd in ('transpose','t'):
                print('Transpose the given CSV file.\n\nUsage: xan transpose [options] [<input>]\n\nCommon options: -o, --output <file>  -d, --delimiter <char>')
            else:
                print('Transforms CSV data so that all rows have the same number of columns.\n\nUsage: xan fixlengths [options] [<input>]\n\nOptions: -l, --length <n>  -H, --trust-header\nCommon options: -o, --output <file>  -d, --delimiter <char>')
            return True
        elif a in ('-d', '--delimiter', '-o', '--output', '-l', '--length'):
            i += 1
            if i >= len(argv):
                raise ValueError('missing value for ' + a)
            v = argv[i]
            if a in ('-d', '--delimiter'): delim = v
            elif a in ('-o', '--output'): target = v
            else: length = int(v)
        elif a.startswith('--length='): length = int(a.split('=',1)[1])
        elif a.startswith('--delimiter='): delim = a.split('=',1)[1]
        elif a == '-H' or a == '--trust-header': trust = True
        elif a.startswith('-') and a != '-':
            raise ValueError('unexpected argument: ' + a)
        elif inp is None: inp = a
        else: raise ValueError('unexpected argument: ' + a)
        i += 1
    if len(delim) != 1:
        raise ValueError('delimiter must be a single character')
    source = open(inp, newline='', encoding='utf-8') if inp and inp != '-' else sys.stdin
    try:
        rows = list(csv.reader(source, delimiter=delim))
    finally:
        if source is not sys.stdin: source.close()
    if trust:
        n = len(rows[0]) if rows else 0
    elif length is not None:
        n = length
    else:
        n = max((len(row) for row in rows), default=0)
    if cmd in ('transpose','t'):
        if rows and any(len(r) != len(rows[0]) for r in rows):
            raise ValueError('CSV records have different lengths')
        rows = [list(col) for col in zip(*rows)] if rows else []
    else:
        rows = [(r[:n] + [''] * max(0, n-len(r))) for r in rows]
    dest = open(target, 'w', newline='', encoding='utf-8') if target else sys.stdout
    try:
        w = csv.writer(dest, delimiter=delim, lineterminator='\n')
        w.writerows(rows)
    finally:
