def singular(s):
    if s.endswith('ies') and len(s)>3: return s[:-3]+'y'
    if s.endswith('ses') and len(s)>3: return s[:-2]
    if s.endswith('s') and not s.endswith('ss'): return s[:-1]
    return s

def run(cmd, argv):
