            else: rename=v
        elif a=='--': pos.extend(argv[i+1:]); break
        elif a.startswith('-') and a!='-': raise ValueError('unexpected option: '+a)
        else: pos.append(a)
        i+=1
    if not pos: raise ValueError('missing column selection')
    if singularize and rename is not None: raise ValueError('cannot use --singularize with --rename')
    if len(delim)!=1: raise ValueError('delimiter must be a single character')
    sel=pos[0]; path=pos[1] if len(pos)>1 else '-'
    src=open(path,newline='',encoding='utf-8-sig') if path!='-' else sys.stdin
